insert into public.sat_wines (id, wine_type, priority, display_label, source, canonical)
select id, wine_type, priority, display_label, source, canonical
from canonical_seed
on conflict (id) do update set
  wine_type = excluded.wine_type,
  priority = excluded.priority,
  display_label = excluded.display_label,
  source = excluded.source,
  canonical = excluded.canonical;

delete from public.sat_wines
where source = 'canonical_wine'
  and id not in ('SAT_WINE_001', 'SAT_WINE_002', 'SAT_WINE_003', 'SAT_WINE_004', 'SAT_WINE_005', 'SAT_WINE_006', 'SAT_WINE_007', 'SAT_WINE_008', 'SAT_WINE_009', 'SAT_WINE_010', 'SAT_WINE_011', 'SAT_WINE_012', 'SAT_WINE_013', 'SAT_WINE_014', 'SAT_WINE_015', 'SAT_WINE_016', 'SAT_WINE_017', 'SAT_WINE_018', 'SAT_WINE_019', 'SAT_WINE_020', 'SAT_WINE_021', 'SAT_WINE_022', 'SAT_WINE_023', 'SAT_WINE_024', 'SAT_WINE_025', 'SAT_WINE_026', 'SAT_WINE_027', 'SAT_WINE_028', 'SAT_WINE_029', 'SAT_WINE_030', 'SAT_WINE_031', 'SAT_WINE_032', 'SAT_WINE_033', 'SAT_WINE_034', 'SAT_WINE_035', 'SAT_WINE_036', 'SAT_WINE_037', 'SAT_WINE_038', 'SAT_WINE_039', 'SAT_WINE_040', 'SAT_WINE_041', 'SAT_WINE_042', 'SAT_WINE_043', 'SAT_WINE_044', 'SAT_WINE_045', 'SAT_WINE_046', 'SAT_WINE_047', 'SAT_WINE_048', 'SAT_WINE_049', 'SAT_WINE_050', 'SAT_WINE_051', 'SAT_WINE_052', 'SAT_WINE_053', 'SAT_WINE_054', 'SAT_WINE_055', 'SAT_WINE_056', 'SAT_WINE_057', 'SAT_WINE_058', 'SAT_WINE_059', 'SAT_WINE_060', 'SAT_WINE_061', 'SAT_WINE_062', 'SAT_WINE_063', 'SAT_WINE_064', 'SAT_WINE_065', 'SAT_WINE_066', 'SAT_WINE_067', 'SAT_WINE_068', 'SAT_WINE_069', 'SAT_WINE_070', 'SAT_WINE_071', 'SAT_WINE_072', 'SAT_WINE_073', 'SAT_WINE_074', 'SAT_WINE_075', 'SAT_WINE_076', 'SAT_WINE_077', 'SAT_WINE_078', 'SAT_WINE_079', 'SAT_WINE_080', 'SAT_WINE_081', 'SAT_WINE_082', 'SAT_WINE_083', 'SAT_WINE_084', 'SAT_WINE_085', 'SAT_WINE_086', 'SAT_WINE_087', 'SAT_WINE_088', 'SAT_WINE_089', 'SAT_WINE_090', 'SAT_WINE_091', 'SAT_WINE_092', 'SAT_WINE_093', 'SAT_WINE_094', 'SAT_WINE_095', 'SAT_WINE_096', 'SAT_WINE_097', 'SAT_WINE_098', 'SAT_WINE_099', 'SAT_WINE_100', 'SAT_WINE_101', 'SAT_WINE_102', 'SAT_WINE_103', 'SAT_WINE_104', 'SAT_WINE_105', 'SAT_WINE_106', 'SAT_WINE_107');

do $$
declare
  actual_count int;
begin
  select count(*) into actual_count
  from public.sat_wines
  where source = 'canonical_wine';

  if actual_count <> 107 then
    raise exception 'sat_wines canonical seed expected 107 rows, found %', actual_count;
  end if;

  if exists (
    select 1
    from public.sat_wines
    where id in ('SAT_WINE_005', 'SAT_WINE_006', 'SAT_WINE_007', 'SAT_WINE_008', 'SAT_WINE_009', 'SAT_WINE_010', 'SAT_WINE_011', 'SAT_WINE_012')
      and wine_type <> 'BLANCO'
  ) then
    raise exception 'SAT_WINE_005..012 must be BLANCO according to canonical catalog';
  end if;

  if exists (
    select 1
    from public.sat_wines
    where source = 'canonical_wine'
      and display_label !~ '^Vino (blanco|tinto|rosado|espumoso|fortificado) — práctica [0-9]+$'
  ) then
    raise exception 'sat_wines display_label must remain blind-safe';
  end if;
end $$;

commit;
